package app.mambo.next;
import org.json.*;import java.nio.file.*;import java.io.*;import java.util.*;
public final class Regression {
 static int checks;static void check(boolean good,String name){if(!good)throw new AssertionError(name);checks++;}static void reject(String value){try{Profiles.parse(value);throw new AssertionError("Accepted invalid profile");}catch(AssertionError e){throw e;}catch(Exception expected){checks++;}}
 static HttpProbe.Response response(String raw,String method)throws Exception{return HttpProbe.readResponse(new ByteArrayInputStream(raw.getBytes("US-ASCII")),method);}
 static void badResponse(String raw){try{response(raw,"GET");throw new AssertionError("Accepted bad response");}catch(AssertionError e){throw e;}catch(Exception expected){checks++;}}
 public static void main(String[] args)throws Exception{
  String uuid="11111111-1111-4111-8111-111111111111",base="vless://"+uuid+"@127.0.0.1:23491";String k=Base64.getEncoder().encodeToString(new byte[32]);
  JSONObject v=Profiles.parse(base+"?security=none&type=tcp#Local%20test");check(v.getString("name").equals("Local test"),"URL name decode");check(v.getInt("port")==23491,"port");
  JSONObject plus=Profiles.parse("trojan://a%2Bb@host.test:443?type=ws&path=%2Fa%2Bb#A+B");check(plus.getString("name").equals("A+B"),"plus fragment preserved");check(plus.getJSONObject("outbound").getJSONObject("settings").getJSONArray("servers").getJSONObject(0).getString("password").equals("a+b"),"plus password preserved");
  JSONObject bracket=Profiles.parse("trojan://test@[::1]:443");check(bracket.getString("host").equals("::1"),"IPv6 literal");
  JSONObject bundle=Profiles.bundle(Base64.getEncoder().encodeToString((base+"\n"+base+"\nss://unsupported\n").getBytes("UTF-8")));check(bundle.getJSONArray("profiles").length()==1,"dedup base64");check(bundle.getInt("skipped")==1,"unsupported count");
  String wg="[Interface]\nPrivateKey = "+k+"\nAddress = 10.2.0.2/32, fd00::2/128\nDNS = 1.1.1.1\n[Peer]\nPublicKey = "+k+"\nPresharedKey = "+k+"\nEndpoint = [::1]:51820\nAllowedIPs = 0.0.0.0/0, ::/0\nPersistentKeepalive = 25\n";
  JSONObject w=Profiles.parse(wg);check(w.getString("protocol").equals("wireguard"),"WG conf");check(w.getJSONObject("outbound").getJSONObject("settings").getJSONArray("address").length()==2,"WG dual stack");check(w.getJSONObject("outbound").getJSONObject("settings").getJSONArray("peers").getJSONObject(0).has("preSharedKey"),"WG preshared key");
  JSONObject wu=Profiles.parse("wg://"+java.net.URLEncoder.encode(k,"UTF-8")+"@127.0.0.1:51820?publickey="+java.net.URLEncoder.encode(k,"UTF-8")+"&address=10.2.0.2%2F32&reserved=1,2,3#WG");check(wu.getJSONObject("outbound").getJSONObject("settings").getJSONArray("reserved").getInt(2)==3,"WG URI reserved");
  reject(wg+"PostUp = rm -rf x\n");reject(wg.replace("10.2.0.2/32","10.2.0.2/99"));reject(base.replace(":23491",":99999"));reject(base.replace(uuid,"wrong"));reject("trojan://secret@host.test:443?allowInsecure=1");reject("wg://bad@host.test:51820?address=10.0.0.2/32&publickey=bad");
  check(Profiles.rules("example.com\n192.168.0.0/16\nfd00::/8","direct").length()==2,"domain and IP rules");String cfg=Profiles.config(v,23492,"lan.test","ads.test","force.test","proxy","1.1.1.1");JSONObject config=new JSONObject(cfg);JSONArray rules=config.getJSONObject("routing").getJSONArray("rules");check(rules.getJSONObject(0).getString("outboundTag").equals("block"),"block priority");check(rules.getJSONObject(2).getString("outboundTag").equals("proxy"),"proxy priority");check(!cfg.contains("privateKey"),"no unwanted WG fields");check(rules.getJSONObject(1).getString("port").equals("53"),"DNS proxy precedes LAN bypass");check(rules.getJSONObject(1).getJSONArray("ip").getString(0).equals("1.1.1.1"),"DNS rule uses configured resolver");
  JSONObject wc=new JSONObject(Profiles.config(w,23492,"","","","proxy","1.1.1.1"));check(wc.getJSONArray("outbounds").getJSONObject(0).getJSONObject("settings").getJSONArray("remoteDNS").getString(0).equals("1.1.1.1"),"WG remoteDNS");
  Path dir=Paths.get(args[0]);Files.createDirectories(dir);Files.write(dir.resolve("vless.json"),cfg.getBytes("UTF-8"));Files.write(dir.resolve("wireguard.json"),wc.toString().getBytes("UTF-8"));Files.write(dir.resolve("wireguard-uri.json"),Profiles.config(wu,23492,"","","","proxy","1.1.1.1").getBytes("UTF-8"));
  for(String transport:new String[]{"tcp","ws","grpc","xhttp","httpupgrade"}){JSONObject p=Profiles.parse("trojan://test@localhost:443?security=tls&type="+transport+"&path=%2Ftest&serviceName=service");Files.write(dir.resolve("trojan-"+transport+".json"),Profiles.config(p,23492,"","","","proxy","1.1.1.1").getBytes("UTF-8"));checks++;}

  JSONObject reality=Profiles.parse(base+"?security=reality&type=tcp&sni=example.com&pbk=GHIUuX6J4PKx2x9Tlm9XspGVD-MPNEpuejxpSgQGXeE&sid=1234&flow=xtls-rprx-vision");Files.write(dir.resolve("vless-reality.json"),Profiles.config(reality,23492,"","","","proxy","1.1.1.1").getBytes("UTF-8"));check(reality.getJSONObject("outbound").getJSONObject("streamSettings").has("realitySettings"),"Reality settings");
  JSONObject vlessTls=Profiles.parse(base+"?security=tls&type=ws&host=example.com&path=%2Fvpn&sni=example.com");Files.write(dir.resolve("vless-tls-ws.json"),Profiles.config(vlessTls,23492,"","","","proxy","1.1.1.1").getBytes("UTF-8"));check(vlessTls.getJSONObject("outbound").getJSONObject("streamSettings").getJSONObject("wsSettings").getString("path").equals("/vpn"),"VLESS WS path");
  check(response("HTTP/1.1 204 No Content\r\n\r\n","GET").reusable,"204 keepalive");check(response("HTTP/1.1 200 OK\r\nContent-Length: 123\r\n\r\n","HEAD").reusable,"HEAD ignores content length");check(response("HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n4\r\ntest\r\n0\r\nTrailer: value\r\n\r\n","GET").reusable,"chunk and trailer");check(!response("HTTP/1.1 200 OK\r\nConnection: close\r\nContent-Length: 0\r\n\r\n","GET").reusable,"closed response");badResponse("HTTP/1.1 200 OK\r\nContent-Length: 2\r\nContent-Length: 3\r\n\r\nabc");badResponse("HTTP/1.1 200 OK\r\nContent-Length: 600000\r\n\r\n");badResponse("HTTP/1.1 200 OK\r\nContent-Length: 10\r\n\r\nshort");badResponse("HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n3\r\nabcXX");
  System.out.println("PASS: "+checks+" regression checks; generated 10 Xray configs");
 }
}
